INSERT INTO _teaser_card_plan (site_id, column_name, old_value, new_value, change_key, reason, premise, evidence) VALUES
    ('364ea265-5078-4181-a4de-46b51309996e'::uuid, 'card_description', 'Monte Bubbonia rises 595 metres in the comune of Mazzarino, three platforms stepping down from west to east, its limestone base buried under marl and a very red sand, crumbly and dusty.', 'Monte Bubbonìa is a 595-metre-high hill located in the comune of Mazzarino, about twenty kilometres from the city of Gela.', 'teaser-card-s018-rollback:364ea265-5078-4181-a4de-46b51309996e:card_description', 'rollback of teaser-card-s018: card_description ''Monte Bubbonìa is a 595-metre-high hill located in the comune of Mazzarino, about twenty kilometres from the city of Gela.'' restored on Monte Bubbonia', 'c4ba21cd977ff35238525cf7251fab37ea5fafbf6c4fa5d2121fa2e667775f22|4035ab3fcaf3946d9155f4802ae674905001235094264825457567ce52bf695d|4035ab3fcaf3946d9155f4802ae674905001235094264825457567ce52bf695d', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-007", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Monte Bubbonia rises 595 metres in the comune of Mazzarino, three platforms stepping down from west to east, its limestone base buried under marl and a very red sand, crumbly and dusty."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-007 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Monte Bubbonia rises 595 metres [S1]; it lies in the comune of Mazzarino [S1]; it consists of three platforms [S2]; the platforms descend from west to east [S2]; its base is limestone [S3]; the limestone base is covered by marl [S3]; the marl is covered by a very red sand [S3]; the sand is very crumbly and dusty [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-021 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Monte Bubbonia is a hill (mountain) (central claim: the kind of place) [SUPPORTED: https://en.wikipedia.org/wiki/Monte_Bubbonia]; It lies in the comune of Mazzarino (Italy) [SUPPORTED: https://en.wikipedia.org/wiki/Monte_Bubbonia]; It rises 595 metres [SUPPORTED: https://en.wikipedia.org/wiki/Monte_Bubbonia]; It has three platforms [SUPPORTED: https://en.wikipedia.org/wiki/Monte_Bubbonia]; The platforms step down from west to east [SUPPORTED: https://en.wikipedia.org/wiki/Monte_Bubbonia]; The hill has a limestone base [SUPPORTED: https://en.wikipedia.org/wiki/Monte_Bubbonia]; The limestone base is buried under marl [SUPPORTED: https://en.wikipedia.org/wiki/Monte_Bubbonia]; The marl is in turn covered by a very red sand [SUPPORTED: https://en.wikipedia.org/wiki/Monte_Bubbonia]; The red sand is crumbly [SUPPORTED: https://en.wikipedia.org/wiki/Monte_Bubbonia]; The red sand is dusty [SUPPORTED: https://en.wikipedia.org/wiki/Monte_Bubbonia]"}]'::jsonb),
    ('36bcb120-d684-4d2b-82d2-e41311e02bb4'::uuid, 'card_description', 'Brougham Castle sits on part of Brocavum, a Roman fort by the rivers Eamont and Lowther, and in its keep a Roman tombstone serves as a ceiling slab. The fort''s earthworks remain unexcavated.', 'The fort survives as earthworks, but no excavation of these has been carried out so far. With the rivers Eamont and Lowther flowing nearby and meeting to the west, the site had natural defences.', 'teaser-card-s018-rollback:36bcb120-d684-4d2b-82d2-e41311e02bb4:card_description', 'rollback of teaser-card-s018: card_description ''The fort survives as earthworks, but no excavation of these has been carried out so far. With the rivers Eamont and Lowther flowing nearby and meeting to the west, the site had natural defences.'' restored on Brocavum', '0df276899175e756a74461d298bc38af79bc1407dd7f5645cb725e3633746c00|bf62a100a96175a1ee84e016858fa112828157b9367a43c362e0f9c1ce1f4946|bf62a100a96175a1ee84e016858fa112828157b9367a43c362e0f9c1ce1f4946', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-007", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Brougham Castle sits on part of Brocavum, a Roman fort by the rivers Eamont and Lowther, and in its keep a Roman tombstone serves as a ceiling slab. The fort''s earthworks remain unexcavated."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-007 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Brougham Castle sits on part of the Brocavum site [S5]; Brocavum is a Roman fort [S1]; the fort is by the rivers Eamont and Lowther [S3]; a Roman tombstone in the castle keep serves as a ceiling slab [S6]; the fort''s earthworks remain unexcavated [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-021 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Brocavum is a Roman fort (at Brougham, near Penrith, Cumbria, England) (central claim) [SUPPORTED: https://en.wikipedia.org/wiki/Brocavum]; Brougham Castle sits on (occupies) part of the Brocavum site [SUPPORTED: https://en.wikipedia.org/wiki/Brocavum]; The fort lies by the rivers Eamont and Lowther [SUPPORTED: https://en.wikipedia.org/wiki/Brougham_Castle]; In the castle keep a Roman tombstone serves as a ceiling slab [SUPPORTED: https://en.wikipedia.org/wiki/Brocavum]; The fort''s earthworks remain (survive) [SUPPORTED: https://en.wikipedia.org/wiki/Brocavum]; The fort''s earthworks are unexcavated [SUPPORTED: https://en.wikipedia.org/wiki/Brocavum]"}]'::jsonb),
    ('36d0cdd3-3586-46c5-bf1e-8cb4a70e1f6c'::uuid, 'card_description', 'Once only a postern in the London city wall, Moorgate led to the marshy open space of Moorfields, its wooden gate shut at night. Damaged in the Great Fire of 1666, it was demolished in 1762.', '3rd century AD. The last of London''s Roman wall gates to be built, Moorgate opened onto the marshy Moorfields beyond the city''s edge — standing for fifteen centuries before demolition in 1762.', 'teaser-card-s018-rollback:36d0cdd3-3586-46c5-bf1e-8cb4a70e1f6c:card_description', 'rollback of teaser-card-s018: card_description "3rd century AD. The last of London''s Roman wall gates to be built, Moorgate opened onto the marshy Moorfields beyond the city''s edge — standing for fifteen centuries before demolition in 1762." restored on Moorgate', '5c7ef4c701f4c702b5a985c6501fcdb0f431f589da46b07c96ff5abeda675d90|2f4b0b685f583428e21f268742640f2a293b43c82453e05d4b0ebf4ec316b4da|2f4b0b685f583428e21f268742640f2a293b43c82453e05d4b0ebf4ec316b4da', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-007", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Once only a postern in the London city wall, Moorgate led to the marshy open space of Moorfields, its wooden gate shut at night. Damaged in the Great Fire of 1666, it was demolished in 1762."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-007 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Moorgate was once only a postern in the London city wall [S3]; it led to the marshy open space of Moorfields [S4]; it had a wooden gate shut at night [S6]; it was damaged in the Great Fire of London in 1666 [S7]; it was demolished in 1762 [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-021 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Moorgate was a gate in the London city wall (one of the City of London''s northern gates) (central claim) [SUPPORTED: https://en.wikipedia.org/wiki/Moorgate]; It was once only a postern in the London city wall [SUPPORTED: https://en.wikipedia.org/wiki/Moorgate]; It led to the marshy open space of Moorfields [SUPPORTED: https://en.wikipedia.org/wiki/Moorgate]; Its gate was wooden and was shut at night [SUPPORTED: https://en.wikipedia.org/wiki/Moorgate]; It was damaged in the Great Fire of 1666 [SUPPORTED: https://en.wikipedia.org/wiki/Moorgate]; It was demolished in 1762 [SUPPORTED: https://en.wikipedia.org/wiki/Moorgate]"}]'::jsonb),
    ('383a0107-b7f7-4431-a752-590f3c0a42b2'::uuid, 'card_description', 'Inhabited since the late Neolithic age, Aartswoud holds a settlement that is an important source for the Beaker culture, where plant remains of einkorn, emmer, barley and flax were found.', 'The area of Aartswoud has been inhabited since the late Neolithic age, and a settlement there is an important source for the Beaker culture.', 'teaser-card-s018-rollback:383a0107-b7f7-4431-a752-590f3c0a42b2:card_description', 'rollback of teaser-card-s018: card_description ''The area of Aartswoud has been inhabited since the late Neolithic age, and a settlement there is an important source for the Beaker culture.'' restored on Aartswoud', '626402084a162bee8269edd8c0316465c95d0a268be126a443012e028c3ca535|f6977a8cd0f99325e8c6cee79936f83e8931d586f5dd3910419080977e8f7fa7|f6977a8cd0f99325e8c6cee79936f83e8931d586f5dd3910419080977e8f7fa7', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-007", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Inhabited since the late Neolithic age, Aartswoud holds a settlement that is an important source for the Beaker culture, where plant remains of einkorn, emmer, barley and flax were found."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-007 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the area has been inhabited since the late Neolithic age [S1]; Aartswoud holds a settlement [S1]; the settlement is an important source for the Beaker culture [S1]; plant remains of einkorn were found at the site [S2]; plant remains of emmer were found at the site [S2]; plant remains of barley were found at the site [S2]; plant remains of flax were found at the site [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-021 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Aartswoud is a village in North Holland (Netherlands) with a prehistoric settlement (central claim: what and where) [SUPPORTED: https://en.wikipedia.org/wiki/Aartswoud]; The area has been inhabited since the late Neolithic age [SUPPORTED: https://en.wikipedia.org/wiki/Aartswoud]; Aartswoud holds a (prehistoric) settlement [SUPPORTED: https://en.wikipedia.org/wiki/Aartswoud]; That settlement is an important source for the Beaker culture [SUPPORTED: https://en.wikipedia.org/wiki/Aartswoud]; Plant remains of einkorn were found at the site [SUPPORTED: https://en.wikipedia.org/wiki/Aartswoud]; Plant remains of emmer were found at the site [SUPPORTED: https://en.wikipedia.org/wiki/Aartswoud]; Plant remains of barley were found at the site [SUPPORTED: https://en.wikipedia.org/wiki/Aartswoud]; Plant remains of flax were found at the site [SUPPORTED: https://en.wikipedia.org/wiki/Aartswoud]"}]'::jsonb),
    ('38d80f05-0d81-48f5-9b96-dfcf85493532'::uuid, 'card_description', 'Jarlshof holds remains from 2500 BC to the 17th century AD: Bronze Age oval houses, an Iron Age broch, a Pictish painted pebble, a Viking longhouse. Its name first appears in an 1821 novel.', 'Shetland''s most layered site runs from 2500 BC through the 17th century — Bronze Age, Iron Age, Pictish, Norse, and Medieval phases stacked in sequence. No site in Britain compresses so many eras.', 'teaser-card-s018-rollback:38d80f05-0d81-48f5-9b96-dfcf85493532:card_description', 'rollback of teaser-card-s018: card_description "Shetland''s most layered site runs from 2500 BC through the 17th century — Bronze Age, Iron Age, Pictish, Norse, and Medieval phases stacked in sequence. No site in Britain compresses so many eras." restored on Jarlshof', '84593fe374748f77a6dda44a5d6d666f5c4832c8f12cd4c8cce11a42ee37bcfa|b7b844890c31e7ab15b20f1f297d9c9aaff4436cfa37402c2cc2d99f16528040|b7b844890c31e7ab15b20f1f297d9c9aaff4436cfa37402c2cc2d99f16528040', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-007", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Jarlshof holds remains from 2500 BC to the 17th century AD: Bronze Age oval houses, an Iron Age broch, a Pictish painted pebble, a Viking longhouse. Its name first appears in an 1821 novel."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-007 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Jarlshof holds remains dating from 2500 BC [S3]; the remains run up to the 17th century AD [S3]; there are Bronze Age oval houses [S4]; there is an Iron Age broch [S5]; there is a Pictish painted pebble [S6]; there is a Viking longhouse [S7]; the name Jarlshof first appears in a novel [S8]; the novel dates from 1821 [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-021 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Jarlshof is a prehistoric archaeological site in Shetland, Scotland (central claim: what and where) [SUPPORTED: https://en.wikipedia.org/wiki/Jarlshof]; It holds remains dating from 2500 BC [SUPPORTED: https://en.wikipedia.org/wiki/Jarlshof]; It holds remains dating up to the 17th century AD [SUPPORTED: https://en.wikipedia.org/wiki/Jarlshof]; There are Bronze Age oval houses [SUPPORTED: https://en.wikipedia.org/wiki/Jarlshof]; There is an Iron Age broch [SUPPORTED: https://en.wikipedia.org/wiki/Jarlshof]; A Pictish painted pebble was found [SUPPORTED: https://en.wikipedia.org/wiki/Jarlshof]; There is a Viking longhouse [SUPPORTED: https://en.wikipedia.org/wiki/Jarlshof]; The name Jarlshof first appears in a novel [SUPPORTED: https://en.wikipedia.org/wiki/Jarlshof]; The novel in which the name first appears dates from 1821 [SUPPORTED: https://en.wikipedia.org/wiki/Jarlshof]"}]'::jsonb),
    ('39461539-85ee-47d9-9f64-b6a6587844ec'::uuid, 'card_description', 'Below the hill of Spartia, near Sesklo, the Spartia Temple gave up spearheads, part of a marble arm and a bronze phiale inscribed in archaic Greek: Tilephilos dedicated me to Herakles.', '8th-4th century BC cult site at Spartia hill near Sesklo, Magnesia. An inscribed dedication names Heracles and Alcmene — found during a rescue excavation alongside the railroad,...', 'teaser-card-s018-rollback:39461539-85ee-47d9-9f64-b6a6587844ec:card_description', 'rollback of teaser-card-s018: card_description ''8th-4th century BC cult site at Spartia hill near Sesklo, Magnesia. An inscribed dedication names Heracles and Alcmene — found during a rescue excavation alongside the railroad,...'' restored on Spartia Temple', '51d6cd9442221d8257e5a78c837df24db635da13a5aa8adabc453877010987d3|41bd3cd7af4581af66ca98ac30a7eefe1e0c6f709eaf01d57f76c051f717e7d9|41bd3cd7af4581af66ca98ac30a7eefe1e0c6f709eaf01d57f76c051f717e7d9', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-008", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Below the hill of Spartia, near Sesklo, the Spartia Temple gave up spearheads, part of a marble arm and a bronze phiale inscribed in archaic Greek: Tilephilos dedicated me to Herakles."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-008 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the site lies below (at the foot of) the hill of Spartia [S1]; it is near the village of Sesklo [S1]; the temple yielded spearheads [S4]; it yielded part of a marble arm (of a statue) [S4]; it yielded a bronze phiale [S5]; the phiale is inscribed in the archaic Greek alphabet [S5]; the inscription reads: Tilephilos dedicated me to Herakles [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-verify-022 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Spartia Temple is a temple (an ancient Greek cult site) in Greece [SUPPORTED: https://en.wikipedia.org/wiki/Spartia_temple]; The temple lies at the foot of the hill of Spartia [SUPPORTED: https://en.wikipedia.org/wiki/Spartia_temple]; The temple lies near the village of Sesklo [SUPPORTED: https://en.wikipedia.org/wiki/Spartia_temple]; The site yielded spearheads [SUPPORTED: https://en.wikipedia.org/wiki/Spartia_temple]; The site yielded part of a marble arm (the arm of a marble statue) [SUPPORTED: https://en.wikipedia.org/wiki/Spartia_temple]; The site yielded a bronze phiale [SUPPORTED: https://en.wikipedia.org/wiki/Spartia_temple]; The phiale is inscribed in the archaic Greek alphabet [SUPPORTED: https://en.wikipedia.org/wiki/Spartia_temple]; The inscription reads: Tilephilos dedicated me to Herakles [SUPPORTED: https://en.wikipedia.org/wiki/Spartia_temple]"}]'::jsonb),
    ('39b42857-adb4-4cfc-ae7e-c3b2672bbc63'::uuid, 'card_description', 'Southwest of Tangier lay Iulia Constantia Zilil, first a Berber town, then one of three colonias Augustus founded in Mauretania Tingitana between 33 and 25 BC for veterans of Actium.', 'Augustus settled Actium veterans here between 33 and 25 BC, building a colonia atop a preexisting Berber town. Only three Roman coloniae existed in Mauretania Tingitana — this was among them.', 'teaser-card-s018-rollback:39b42857-adb4-4cfc-ae7e-c3b2672bbc63:card_description', 'rollback of teaser-card-s018: card_description ''Augustus settled Actium veterans here between 33 and 25 BC, building a colonia atop a preexisting Berber town. Only three Roman coloniae existed in Mauretania Tingitana — this was among them.'' restored on Iulia Constantia Zilil', '8d72ccc4666ada781fc674daa009470318d1c979bb5ace6959c386da61298b2c|3eae816c4b9ae7cd3181aee3f319c53dc65bb3951cece5bc9b223d4e53e2c8a6|3eae816c4b9ae7cd3181aee3f319c53dc65bb3951cece5bc9b223d4e53e2c8a6', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-008", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Southwest of Tangier lay Iulia Constantia Zilil, first a Berber town, then one of three colonias Augustus founded in Mauretania Tingitana between 33 and 25 BC for veterans of Actium."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-008 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the site lies southwest of Tangier [S1]; it was first a Berber town [S3]; it later became one of three colonias in Mauretania Tingitana [S2, S3]; the three colonias were founded by Augustus [S2]; they were founded between 33 and 25 BC [S2]; they were founded for veterans of the battle of Actium [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-verify-022 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Iulia Constantia Zilil was an ancient Roman city (a colonia) in Morocco [SUPPORTED: https://en.wikipedia.org/wiki/Iulia_Constantia_Zilil]; Zilil lay southwest of Tangier [SUPPORTED: https://en.wikipedia.org/wiki/Iulia_Constantia_Zilil]; Zilil was first a Berber town, before it became a Roman colonia [SUPPORTED: https://en.wikipedia.org/wiki/Iulia_Constantia_Zilil]; Zilil was one of three colonias [SUPPORTED: https://en.wikipedia.org/wiki/Iulia_Constantia_Zilil]; The three colonias were in Mauretania Tingitana [SUPPORTED: https://en.wikipedia.org/wiki/Iulia_Constantia_Zilil]; The three colonias were founded by Augustus [SUPPORTED: https://en.wikipedia.org/wiki/Iulia_Constantia_Zilil]; The three colonias were founded between 33 and 25 BC [SUPPORTED: https://en.wikipedia.org/wiki/Iulia_Valentia_Banasa]; The colonias were founded for veterans of the battle of Actium [SUPPORTED: https://en.wikipedia.org/wiki/Iulia_Constantia_Zilil]"}]'::jsonb),
    ('3a229dc1-93fd-4ff5-93a9-6c3c61cc9e22'::uuid, 'card_description', 'In the foothills of Mount Ida on Crete, Zominthos holds a large two-story Minoan building unveiled in 1982, unusually well-preserved, some of its walls still rising up to 3 meters.', 'A Minoan building from 1800-1600 BC on the path from Knossos to the great cave sanctuary of Mount Ida. Signs of permanent settlement include a large two-story structure.', 'teaser-card-s018-rollback:3a229dc1-93fd-4ff5-93a9-6c3c61cc9e22:card_description', 'rollback of teaser-card-s018: card_description ''A Minoan building from 1800-1600 BC on the path from Knossos to the great cave sanctuary of Mount Ida. Signs of permanent settlement include a large two-story structure.'' restored on Zominthos', '498eb905346eec1c90f32575ee42997a73e124158bffb13253bb733ee24e7044|35da4eed2e86392b7322c1732591a375b922239663b30d9a4f81a4bf02fd1223|35da4eed2e86392b7322c1732591a375b922239663b30d9a4f81a4bf02fd1223', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-rewrite-v-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "In the foothills of Mount Ida on Crete, Zominthos holds a large two-story Minoan building unveiled in 1982, unusually well-preserved, some of its walls still rising up to 3 meters."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-v-001 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Zominthos is in the foothills of Mount Ida [S1]; it is on Crete [S1]; it holds a large building [S3, S4]; the building is two-story [S4]; the building is Minoan [S3, S4]; the building was unveiled in 1982 [S4]; the building is unusually well-preserved [S7]; some of its remaining walls rise up to 3 meters [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify2-003 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Zominthos is a Minoan site best known for a large Minoan building (central claim: a site with a Minoan building) [SUPPORTED: https://en.wikipedia.org/wiki/Zominthos]; Zominthos lies in the foothills of Mount Ida [SUPPORTED: https://en.wikipedia.org/wiki/Zominthos]; Zominthos is on the island of Crete [SUPPORTED: https://en.wikipedia.org/wiki/Zominthos]; The building at Zominthos is large [SUPPORTED: https://en.wikipedia.org/wiki/Zominthos]; The building at Zominthos has two stories [SUPPORTED: https://en.wikipedia.org/wiki/Zominthos]; The Minoan building was unveiled in 1982 [SUPPORTED: https://en.wikipedia.org/wiki/Zominthos]; The building is unusually well-preserved [SUPPORTED: https://en.wikipedia.org/wiki/Zominthos]; Some of the building''s walls are still standing (remaining walls) [SUPPORTED: https://en.wikipedia.org/wiki/Zominthos]; The tallest surviving walls rise up to 3 meters [SUPPORTED: https://en.wikipedia.org/wiki/Zominthos]"}]'::jsonb),
    ('3c612fb4-3639-4124-8e26-58457c82376a'::uuid, 'card_description', 'Beinan Cultural Park is an archaeological site in Taitung City, home to the largest and most complete prehistoric settlement ever discovered in Taiwan, with more than 1,600 burial sites.', 'The largest prehistoric settlement ever found on this island, with over 1,600 burial sites across 10,000 square metres. The earliest remains date to the 4th millennium BC.', 'teaser-card-s018-rollback:3c612fb4-3639-4124-8e26-58457c82376a:card_description', 'rollback of teaser-card-s018: card_description ''The largest prehistoric settlement ever found on this island, with over 1,600 burial sites across 10,000 square metres. The earliest remains date to the 4th millennium BC.'' restored on Beinan Cultural Park', 'b3ad00666e260e513bc45e6fb5455fc23fe26519221a5f26a5c13ff57f7889d2|7c48e611f3cdf1535d6541162db499fe14d9935f6a0b534aee757dd51bf88b78|7c48e611f3cdf1535d6541162db499fe14d9935f6a0b534aee757dd51bf88b78', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-rewrite-v-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Beinan Cultural Park is an archaeological site in Taitung City, home to the largest and most complete prehistoric settlement ever discovered in Taiwan, with more than 1,600 burial sites."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-v-001 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the park is an archaeological site [S1]; it is in Taitung City [S1]; it is the site of the largest and most complete prehistoric settlement ever discovered in Taiwan [S2]; it contains more than 1,600 burial sites [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify2-003 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Beinan (Peinan) Cultural Park is an archaeological site (central claim: a prehistoric settlement site) [SUPPORTED: https://en.wikipedia.org/wiki/Peinan_Site_Park]; The site is in Taitung City, Taiwan [SUPPORTED: https://en.wikipedia.org/wiki/Peinan_Site_Park]; It is the site of the largest prehistoric settlement ever discovered in Taiwan [SUPPORTED: https://en.wikipedia.org/wiki/Peinan_Site_Park]; It is the site of the most complete prehistoric settlement ever discovered in Taiwan [SUPPORTED: https://en.wikipedia.org/wiki/Peinan_Site_Park]; It contains more than 1,600 burial sites [SUPPORTED: https://en.wikipedia.org/wiki/Peinan_Site_Park]"}]'::jsonb),
    ('3d20c37f-30ac-405f-8dc4-16c40e7cbeae'::uuid, 'card_description', 'At Bury Hill, Ariconium was a Roman road station, with a pre-Roman coin minted by Cunobelin among its finds. It was abandoned, but precisely when and under what circumstances is unknown.', 'Ariconium was a road station of Roman Britain mentioned in Iter XIII of the Iter Britanniarum of the Antonine Itineraries.', 'teaser-card-s018-rollback:3d20c37f-30ac-405f-8dc4-16c40e7cbeae:card_description', 'rollback of teaser-card-s018: card_description ''Ariconium was a road station of Roman Britain mentioned in Iter XIII of the Iter Britanniarum of the Antonine Itineraries.'' restored on Ariconium', 'bd590e0f09ff488a23f8fbad3162103dfba95379f29016374a9fb293646a84a2|225aa0e62e94dd1ce3d88bcea61d09e2d9c5799bb52fd13269c673d36858480d|225aa0e62e94dd1ce3d88bcea61d09e2d9c5799bb52fd13269c673d36858480d', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-rewrite-v-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "At Bury Hill, Ariconium was a Roman road station, with a pre-Roman coin minted by Cunobelin among its finds. It was abandoned, but precisely when and under what circumstances is unknown."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-v-001 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Ariconium was at Bury Hill [S2]; it was a Roman road station [S1]; its finds include a pre-Roman coin minted by Cunobelin [S5]; it was abandoned [S4]; precisely when and under what circumstances it was abandoned is unknown [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify2-003 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Ariconium was a Roman road station (central claim: a road station of Roman Britain) [SUPPORTED: https://en.wikipedia.org/wiki/Ariconium]; Ariconium was at Bury Hill [SUPPORTED: https://en.wikipedia.org/wiki/Ariconium]; A pre-Roman coin minted by Cunobelin is among the finds at Ariconium [SUPPORTED: https://en.wikipedia.org/wiki/Ariconium]; The site was abandoned [SUPPORTED: https://en.wikipedia.org/wiki/Ariconium]; Precisely when and under what circumstances Ariconium was abandoned is unknown [SUPPORTED: https://en.wikipedia.org/wiki/Ariconium]"}]'::jsonb),
    ('3d801ecb-4453-4ce3-85db-dce392c67c9d'::uuid, 'card_description', 'On granite above a creek, the Ganjnameh Ancient Inscriptions praise Ahura Mazda in Old Persian, Neo-Babylonian and Neo-Elamite. Locals believed they held the code to a hidden treasure.', 'Two Achaemenid cuneiform inscriptions in three languages carved into granite above a creek. Locals believed the carvings were a secret code to hidden treasure.', 'teaser-card-s018-rollback:3d801ecb-4453-4ce3-85db-dce392c67c9d:card_description', 'rollback of teaser-card-s018: card_description ''Two Achaemenid cuneiform inscriptions in three languages carved into granite above a creek. Locals believed the carvings were a secret code to hidden treasure.'' restored on Ganjnameh Ancient Inscriptions', '2e57922ff058e613b54c845ab94852e9906f9d47cc76eef17a9f4fa1ccd49c1d|4ae9ec84c8a21dabdc4e90666f0432e0d11ac05186b8827915e8f1a5de8d571c|4ae9ec84c8a21dabdc4e90666f0432e0d11ac05186b8827915e8f1a5de8d571c', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-008", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "On granite above a creek, the Ganjnameh Ancient Inscriptions praise Ahura Mazda in Old Persian, Neo-Babylonian and Neo-Elamite. Locals believed they held the code to a hidden treasure."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-008 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the inscriptions are carved on granite [S1]; the rock is above a creek [S1]; the inscriptions praise Ahura Mazda [S2]; they are written in Old Persian, Neo-Babylonian and Neo-Elamite [S2]; locals believed the inscriptions held the code to a hidden treasure [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-023 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Ganjnameh (the Ganjnameh Ancient Inscriptions) is a site of ancient royal rock inscriptions: two trilingual Achaemenid royal inscriptions [SUPPORTED: https://en.wikipedia.org/wiki/Ganjnameh]; The site lies near Hamadan in western Iran [SUPPORTED: https://en.wikipedia.org/wiki/Ganjnameh]; The inscriptions are carved on granite above a creek [SUPPORTED: https://en.wikipedia.org/wiki/Ganjnameh]; The inscriptions praise Ahura Mazda [SUPPORTED: https://en.wikipedia.org/wiki/Ganjnameh]; The inscriptions are written in Old Persian, Neo-Babylonian and Neo-Elamite [SUPPORTED: https://en.wikipedia.org/wiki/Ganjnameh]; Locals believed the inscriptions held the code to a hidden treasure [SUPPORTED: https://en.wikipedia.org/wiki/Ganjnameh]"}]'::jsonb),
    ('3df64c15-9caf-430f-b6d0-82bd2b15ddd1'::uuid, 'card_description', 'Work to remove a road in 1992 uncovered Pyramid G1-d, a satellite pyramid of Khufu''s complex on the Giza plateau, originally 13.8 metres high, its slope very similar to the Great Pyramid''s.', 'The pyramid was discovered in 1992 about 25 metres east-southeast of the southeast corner of the Great Pyramid, and about 7 metres west of the subsidiary pyramids G1-b and G1-c.', 'teaser-card-s018-rollback:3df64c15-9caf-430f-b6d0-82bd2b15ddd1:card_description', 'rollback of teaser-card-s018: card_description ''The pyramid was discovered in 1992 about 25 metres east-southeast of the southeast corner of the Great Pyramid, and about 7 metres west of the subsidiary pyramids G1-b and G1-c.'' restored on Pyramid G1-d', '514f7bdb93c76df69dfe1b5a29c35a387ddd782dcc8809d4dec1f0491ae05ca1|5b1a7b1ff53ff1857179178797c0c69aa2e421964f9253ea548020fa74c4b0bc|5b1a7b1ff53ff1857179178797c0c69aa2e421964f9253ea548020fa74c4b0bc', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-rewrite1-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Work to remove a road in 1992 uncovered Pyramid G1-d, a satellite pyramid of Khufu''s complex on the Giza plateau, originally 13.8 metres high, its slope very similar to the Great Pyramid''s."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check1-001 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "work to remove a road in 1992 led to the discovery of Pyramid G1-d [S2]; Pyramid G1-d is a satellite pyramid of Khufu''s pyramid complex [S1]; it lies on the Giza plateau [S1]; it was originally 13.8 metres high [S3]; its mean slope is very similar to that of the Great Pyramid [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-023 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Pyramid G1-d is a satellite pyramid of Khufu''s pyramid complex [SUPPORTED: https://en.wikipedia.org/wiki/Pyramid_G1-d]; Khufu''s complex, with Pyramid G1-d, lies on the Giza plateau (Egypt) [SUPPORTED: https://en.wikipedia.org/wiki/Pyramid_G1-d]; Pyramid G1-d was uncovered in 1992 [SUPPORTED: https://en.wikipedia.org/wiki/Pyramid_G1-d]; It was uncovered during work to remove a road [SUPPORTED: https://en.wikipedia.org/wiki/Pyramid_G1-d]; Its original height was 13.8 metres [SUPPORTED: https://en.wikipedia.org/wiki/Pyramid_G1-d]; Its slope is very similar to that of the Great Pyramid [SUPPORTED: https://en.wikipedia.org/wiki/Pyramid_G1-d]"}]'::jsonb),
    ('3e27c892-40de-4be9-a3fd-396e17d3c86d'::uuid, 'card_description', 'Carved in rock under Ashoka on the edge of the vanished Sudarshan Lake, the Buddhist Caves of Khapra Kodiya are the oldest of the Junagadh group. Now only the highest story remains.', 'Buddhist caves carved during Emperor Ashoka''s reign in the 3rd century BC. They are the earliest monastic settlement in the area, hewn directly from rock.', 'teaser-card-s018-rollback:3e27c892-40de-4be9-a3fd-396e17d3c86d:card_description', 'rollback of teaser-card-s018: card_description "Buddhist caves carved during Emperor Ashoka''s reign in the 3rd century BC. They are the earliest monastic settlement in the area, hewn directly from rock." restored on Buddhist Caves of Khapra Kodiya', '12b7ef88ec7a183d6a6e8ef0ab6232a655aa03ce1ca7d852ec312200b7ad8907|da6965f9ff26cf760a4b80e54e359247fd7814b2a7cab6e602af92dceabdcbbf|da6965f9ff26cf760a4b80e54e359247fd7814b2a7cab6e602af92dceabdcbbf', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-008", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Carved in rock under Ashoka on the edge of the vanished Sudarshan Lake, the Buddhist Caves of Khapra Kodiya are the oldest of the Junagadh group. Now only the highest story remains."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-008 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the caves were carved in rock [S5]; they were carved under (during the reign of) Ashoka [S3, S5]; they lie on the edge of the Sudarshan Lake [S6]; the lake no longer exists [S6]; they are Buddhist caves of the Junagadh group [S1]; they are the oldest of the caves in the Junagadh group [S2]; now only the highest story remains [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-023 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Buddhist Caves of Khapra Kodiya are part of the Junagadh Buddhist cave group [SUPPORTED: https://en.wikipedia.org/wiki/Khapra_Kodiya_Caves]; The Junagadh cave groups, which include the Khapra Kodiya Caves, are in Junagadh district, Gujarat, India [SUPPORTED: https://en.wikipedia.org/wiki/Junagadh_Buddhist_Cave_Groups]; The Khapra Kodiya caves are rooms carved in rock, built as monks'' quarters [SUPPORTED: https://gujarattourism.com/saurashtra/junagadh/buddhist-caves.html]; The caves were carved in rock under (during the reign of) Ashoka [SUPPORTED: https://gujarattourism.com/saurashtra/junagadh/buddhist-caves.html]; The caves lie along the edge of the Sudarshan Lake [SUPPORTED: https://gujarattourism.com/saurashtra/junagadh/buddhist-caves.html]; The Sudarshan Lake is vanished (no longer exists) [SUPPORTED: https://gujarattourism.com/saurashtra/junagadh/buddhist-caves.html]; They are the oldest of the Junagadh group of caves [SUPPORTED: https://en.wikipedia.org/wiki/Khapra_Kodiya_Caves]; Now only the highest story of the Khapra Kodiya caves remains [SUPPORTED: https://gujarattourism.com/saurashtra/junagadh/buddhist-caves.html]"}]'::jsonb),
    ('3f512971-679b-4f40-8f5e-1467424ce605'::uuid, 'card_description', 'Only 70 metres from the Dolmen of Menga stands the Dolmen de Viera, a single-chamber tomb found in February 1903 by the brothers José Viera Fuentes and Antonio Viera Fuentes.', 'The Dolmen de Viera was built in the Copper Age, 3510-3020 BC approx. It has had the status of a National monument since 1923.', 'teaser-card-s018-rollback:3f512971-679b-4f40-8f5e-1467424ce605:card_description', 'rollback of teaser-card-s018: card_description ''The Dolmen de Viera was built in the Copper Age, 3510-3020 BC approx. It has had the status of a National monument since 1923.'' restored on Dolmen de Viera', '4a9645b14c221c61e809f84c5276c92473c2577d139e7e4e201b9a919708be75|24b0efebd5d7d2ebe561f1329d029c19238497292fa1eb2704e9ff9463a934ff|24b0efebd5d7d2ebe561f1329d029c19238497292fa1eb2704e9ff9463a934ff', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-rewrite-v-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Only 70 metres from the Dolmen of Menga stands the Dolmen de Viera, a single-chamber tomb found in February 1903 by the brothers José Viera Fuentes and Antonio Viera Fuentes."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-v-001 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the Dolmen de Viera is only 70 metres from the Dolmen of Menga [S2]; the Dolmen de Viera is a single-chamber tomb [S1]; it was found in February 1903 [S3, W1]; it was found by two brothers [S3, W1]; the brothers are José Viera Fuentes and Antonio Viera Fuentes [W1]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify2-003 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Dolmen de Viera is a dolmen, i.e. a megalithic tomb at Antequera (central claim: a tomb) [SUPPORTED: https://en.wikipedia.org/wiki/Dolmen_de_Viera]; The Dolmen de Viera is a single-chamber tomb [SUPPORTED: https://en.wikipedia.org/wiki/Dolmen_de_Viera]; The Dolmen de Viera stands only 70 metres from the Dolmen of Menga [SUPPORTED: https://en.wikipedia.org/wiki/Dolmen_de_Viera]; The dolmen was found in February 1903 [SUPPORTED: https://en.wikipedia.org/wiki/Dolmen_de_Viera]; The dolmen was found by two brothers [SUPPORTED: https://es.wikipedia.org/wiki/Dolmen_de_Viera]; The brothers were José Viera Fuentes and Antonio Viera Fuentes [SUPPORTED: https://es.wikipedia.org/wiki/Dolmen_de_Viera]"}, {"source": "web fact W1", "url": "https://es.wikipedia.org/wiki/Dolmen_de_Viera", "quote": "fue descubierto en febrero de 1903 por los hermanos José Viera Fuentes y Antonio Viera Fuentes"}]'::jsonb),
    ('3f888db6-1b30-44c7-b2f6-3effec34f650'::uuid, 'card_description', 'Once at the edge of a lake, now in arid land at Orce, Barranco León yielded the milk tooth of a child of 10 years, hailed as the earliest anatomical evidence for humans in Western Europe.', 'A 1.4-million-year-old site that yielded a child''s milk tooth -- the earliest anatomical evidence of humans in Western Europe at the time of its dating.', 'teaser-card-s018-rollback:3f888db6-1b30-44c7-b2f6-3effec34f650:card_description', 'rollback of teaser-card-s018: card_description "A 1.4-million-year-old site that yielded a child''s milk tooth -- the earliest anatomical evidence of humans in Western Europe at the time of its dating." restored on Barranco León', '4cadd37ffc37cab9ebdcb3b0e275a1c994117cb94331097e55ae1e94509132b7|4de04c0b5fb4f15b433b75d99fd530a7b5a9af52083b4a37e8673d9e446c442d|4de04c0b5fb4f15b433b75d99fd530a7b5a9af52083b4a37e8673d9e446c442d', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-008", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Once at the edge of a lake, now in arid land at Orce, Barranco León yielded the milk tooth of a child of 10 years, hailed as the earliest anatomical evidence for humans in Western Europe."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-008 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the site was once at the edge of a lake [S5]; it is now in arid land [S5]; it is at Orce [S1]; it yielded the milk tooth of a child of 10 years [S2]; the tooth''s owner was hailed as having left the earliest anatomical evidence for humans in Western Europe [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-023 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Barranco León is an archaeological site at Orce, Spain [SUPPORTED: https://en.wikipedia.org/wiki/Barranco_Le%C3%B3n]; Barranco León yielded the milk tooth of a child of 10 years [SUPPORTED, no proving quote: https://www.museosdeandalucia.es/web/museoarqueologicodegranada/obras-singulares/-/asset_publisher/GRnu6ntjtLfp/content/molar-de-hominido-homo-s-p-?inheritRedirect=true]; The tooth was hailed as the earliest anatomical evidence for humans in Western Europe [SUPPORTED: https://en.wikipedia.org/wiki/Barranco_Le%C3%B3n]; The site was once at the edge of a lake [SUPPORTED: https://en.wikipedia.org/wiki/Barranco_Le%C3%B3n]; The site is now in an arid area [SUPPORTED: https://en.wikipedia.org/wiki/Barranco_Le%C3%B3n]"}]'::jsonb),
    ('3fccdb58-627d-4e17-b711-15921d2b681d'::uuid, 'card_description', 'Roughly 60 km southwest of Carthage, Roman Thuburbo Majus received a Capitolium in 168. A 1916 dig found a tetrastyle temple; the house of Bacchus and Ariadne was excavated in 1925.', 'Ruins of a large Roman city with a forum, amphitheatre, temples, baths, and houses. None are fully restored, but the scale reveals a prosperous settlement.', 'teaser-card-s018-rollback:3fccdb58-627d-4e17-b711-15921d2b681d:card_description', 'rollback of teaser-card-s018: card_description ''Ruins of a large Roman city with a forum, amphitheatre, temples, baths, and houses. None are fully restored, but the scale reveals a prosperous settlement.'' restored on Thuburbo Majus', '09e92081fa0dfb93c3f45ed935a54b97a5e5692049037f95aef18c30f351d8b5|0feb060771560e1589e62610ec415be9cce49ae9bc54655c977eb4d4149ac061|0feb060771560e1589e62610ec415be9cce49ae9bc54655c977eb4d4149ac061', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-rewrite-v-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Roughly 60 km southwest of Carthage, Roman Thuburbo Majus received a Capitolium in 168. A 1916 dig found a tetrastyle temple; the house of Bacchus and Ariadne was excavated in 1925."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-v-001 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Thuburbo Majus is roughly 60 km southwest of Carthage [S2]; it is a Roman site [S1]; it received a Capitolium in 168 [S4]; a 1916 excavation found a tetrastyle temple [S5]; the house of Bacchus and Ariadne was excavated in 1925 [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify2-003 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Thuburbo Majus is a large Roman site (city) in Tunisia (central claim: a Roman town) [SUPPORTED: https://en.wikipedia.org/wiki/Thuburbo_Majus]; Thuburbo Majus lies roughly 60 km southwest of Carthage [SUPPORTED: https://en.wikipedia.org/wiki/Thuburbo_Majus]; Thuburbo Majus received a Capitolium in 168 [SUPPORTED: https://en.wikipedia.org/wiki/Thuburbo_Majus]; A 1916 dig found a tetrastyle temple [SUPPORTED: https://en.wikipedia.org/wiki/Thuburbo_Majus]; The house of Bacchus and Ariadne was excavated in 1925 [SUPPORTED: https://en.wikipedia.org/wiki/Thuburbo_Majus]"}]'::jsonb),
    ('4014b1e9-bf5f-42b9-bb06-c7e940b84be5'::uuid, 'card_description', 'Greek epigrams painted on a wall in a small room beside the peristyle gave the House of the Greek Epigrams in Pompeii its name. Its atrium yielded a gold necklace with emeralds and pearls.', 'Named for wall paintings inscribed with Greek epigrams, this Pompeii house was created by merging two older dwellings. Over twenty painted panels decorated its rooms.', 'teaser-card-s018-rollback:4014b1e9-bf5f-42b9-bb06-c7e940b84be5:card_description', 'rollback of teaser-card-s018: card_description ''Named for wall paintings inscribed with Greek epigrams, this Pompeii house was created by merging two older dwellings. Over twenty painted panels decorated its rooms.'' restored on House of the Greek Epigrams, Pompeii', '2a1644cc602f987937a3ea27f2f80adc0ed96a82792e0d1c1d5d5c8f995fdaa2|295f689b6f3d01d36dff962daa5d2944774bb26037c04b5dedd53c77f6515111|295f689b6f3d01d36dff962daa5d2944774bb26037c04b5dedd53c77f6515111', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-rewrite-v-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Greek epigrams painted on a wall in a small room beside the peristyle gave the House of the Greek Epigrams in Pompeii its name. Its atrium yielded a gold necklace with emeralds and pearls."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-v-002 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the house is in Pompeii [S1]; the house is named after Greek epigrams (inscriptions in wall paintings) [S2]; the epigrams are painted on a wall [S2]; they are in a small room [S2]; the room is beside the peristyle [S2]; the atrium yielded a necklace of gold with emeralds and pearls [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-verify2-004 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The House of the Greek Epigrams is a Roman residence (a house) in Pompeii [SUPPORTED: https://en.wikipedia.org/wiki/House_of_the_Greek_Epigrams]; The house is in Pompeii, in Italy [SUPPORTED: https://en.wikipedia.org/wiki/Pompeii]; The house is named after Greek epigrams [SUPPORTED: https://en.wikipedia.org/wiki/House_of_the_Greek_Epigrams]; The Greek epigrams are painted on a wall [SUPPORTED: https://en.wikipedia.org/wiki/House_of_the_Greek_Epigrams]; The epigrams are in a small room [SUPPORTED: https://en.wikipedia.org/wiki/House_of_the_Greek_Epigrams]; The small room is beside the peristyle [SUPPORTED: https://en.wikipedia.org/wiki/House_of_the_Greek_Epigrams]; A necklace was recovered in the atrium [SUPPORTED: https://en.wikipedia.org/wiki/House_of_the_Greek_Epigrams]; The necklace was of gold [SUPPORTED: https://en.wikipedia.org/wiki/House_of_the_Greek_Epigrams]; The necklace had emeralds and pearls [SUPPORTED: https://en.wikipedia.org/wiki/House_of_the_Greek_Epigrams]"}]'::jsonb),
    ('402f38a8-f484-49eb-99bb-d508093abbd3'::uuid, 'card_description', 'Nine megaliths, the nine sisters in Cornish, form the Nine Maidens Stone Row, a late neolithic line approximately 108 metres long, aligned towards a moorland stone known as the Fiddler.', 'A 108-metre-long Neolithic stone row of nine megaliths, also known in Cornish as Naw-voz, meaning "the nine sisters." Stones range from 0.8 to 1.4 metres tall.', 'teaser-card-s018-rollback:402f38a8-f484-49eb-99bb-d508093abbd3:card_description', 'rollback of teaser-card-s018: card_description ''A 108-metre-long Neolithic stone row of nine megaliths, also known in Cornish as Naw-voz, meaning "the nine sisters." Stones range from 0.8 to 1.4 metres tall.'' restored on Nine Maidens Stone Row', '02fe521af9ee4956741384748351cafca6f8e935adf73cecfc8f69e73ae93080|088e7cfd14417efaa1da6268eb2fd27365411ff2a88fdb77b957d1b296f567b2|088e7cfd14417efaa1da6268eb2fd27365411ff2a88fdb77b957d1b296f567b2', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-008", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Nine megaliths, the nine sisters in Cornish, form the Nine Maidens Stone Row, a late neolithic line approximately 108 metres long, aligned towards a moorland stone known as the Fiddler."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-008 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the row consists of nine megaliths [S4]; in Cornish the row is called the nine sisters [S2]; it is a late neolithic stone row [S3]; the row is approximately 108 metres long [S5]; it is aligned towards a stone known as the Fiddler [S7]; the Fiddler lies on the moorland [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-024 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Nine Maidens Stone Row is a stone row (alignment) in Cornwall, England [SUPPORTED: https://en.wikipedia.org/wiki/Nine_Maidens_stone_row]; The row consists of nine megaliths [SUPPORTED: https://en.wikipedia.org/wiki/Nine_Maidens_stone_row]; In Cornish the name means the nine sisters [SUPPORTED: https://en.wikipedia.org/wiki/Nine_Maidens_stone_row]; The stone row is late Neolithic in date [SUPPORTED: https://en.wikipedia.org/wiki/Nine_Maidens_stone_row]; The row is approximately 108 metres long [SUPPORTED: https://en.wikipedia.org/wiki/Nine_Maidens_stone_row]; The row is aligned towards a moorland stone known as the Fiddler [SUPPORTED: https://en.wikipedia.org/wiki/Nine_Maidens_stone_row]"}]'::jsonb),
    ('411cacb0-6312-4465-81f2-76417d209c17'::uuid, 'card_description', 'Named from the Old English for kite, a bird of prey, Kit Hill rises 334 metres, born of magma forced into sedimentary rock. Its minerals were mined in the 18th and early 19th centuries.', 'Kit Hill is the highest point in the Tamar Valley Area of Outstanding Natural Beauty.', 'teaser-card-s018-rollback:411cacb0-6312-4465-81f2-76417d209c17:card_description', 'rollback of teaser-card-s018: card_description ''Kit Hill is the highest point in the Tamar Valley Area of Outstanding Natural Beauty.'' restored on Kit Hill', '4b8aee52b0124020d390456650bd1162cd0aa557b24e19f21f50dec241e244a3|8c457b17d33f22774b0ddb3ddb475195e0fc1642b3791eb6fde797997cef7a7f|8c457b17d33f22774b0ddb3ddb475195e0fc1642b3791eb6fde797997cef7a7f', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-008", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Named from the Old English for kite, a bird of prey, Kit Hill rises 334 metres, born of magma forced into sedimentary rock. Its minerals were mined in the 18th and early 19th centuries."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-008 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the name comes from the Old English word for kite [S2]; a kite is a bird of prey [S2]; the hill rises 334 metres [S1]; the hill was formed by magma intruding into sedimentary rock [S4]; its mineral deposits were mined in the 18th and early 19th centuries [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-024 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Kit Hill is a hill (in southeast Cornwall) [SUPPORTED: https://en.wikipedia.org/wiki/Kit_Hill]; The name Kit comes from the Old English for kite, a bird of prey [SUPPORTED: https://en.wikipedia.org/wiki/Kit_Hill]; Kit Hill rises 334 metres [SUPPORTED, no proving quote: https://en.wikipedia.org/wiki/Kit_Hill]; The hill was born of magma forced (intruded) into sedimentary rock [SUPPORTED: https://en.wikipedia.org/wiki/Kit_Hill]; Its minerals were mined in the 18th and early 19th centuries [SUPPORTED: https://en.wikipedia.org/wiki/Kit_Hill]"}]'::jsonb),
    ('4297c23a-44ec-49e3-a34f-7715a16d7620'::uuid, 'card_description', 'Three stones mark the main chamber of Five Wells, a Neolithic tomb on Taddington Moor with paved floors. Its first excavator, Thomas Bateman, found remains of at least twelve skeletons.', 'A Neolithic chambered tomb over 20 metres across on Taddington Moor, with paved burial chambers. Human bones from at least twelve individuals were found inside.', 'teaser-card-s018-rollback:4297c23a-44ec-49e3-a34f-7715a16d7620:card_description', 'rollback of teaser-card-s018: card_description ''A Neolithic chambered tomb over 20 metres across on Taddington Moor, with paved burial chambers. Human bones from at least twelve individuals were found inside.'' restored on Five Wells', 'b341bb1f620e619678de023643900d7641dd883c7f4d0f61a3a2abf58c2ddadf|24ea62ec6c0f7eb3fa7f358064dedc91c632a94789f5b6071d712ab7312d574f|24ea62ec6c0f7eb3fa7f358064dedc91c632a94789f5b6071d712ab7312d574f', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-008", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Three stones mark the main chamber of Five Wells, a Neolithic tomb on Taddington Moor with paved floors. Its first excavator, Thomas Bateman, found remains of at least twelve skeletons."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-008 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "three stones mark the main chamber [S3]; Five Wells is a Neolithic tomb [S1]; it lies on Taddington Moor [S1]; the chambers have paved floors [S5]; Thomas Bateman was its first excavator [S4]; Bateman found remains of at least twelve skeletons [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-024 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Five Wells is a chambered tomb (a tomb) [SUPPORTED: https://en.wikipedia.org/wiki/Five_Wells]; Five Wells is Neolithic in date [SUPPORTED: https://en.wikipedia.org/wiki/Five_Wells]; Five Wells lies on Taddington Moor [SUPPORTED: https://en.wikipedia.org/wiki/Five_Wells]; Three stones mark the main chamber of Five Wells [SUPPORTED: https://en.wikipedia.org/wiki/Five_Wells]; The chambers of Five Wells have paved floors [SUPPORTED: https://en.wikipedia.org/wiki/Five_Wells]; Thomas Bateman was the first excavator of Five Wells [SUPPORTED: https://en.wikipedia.org/wiki/Five_Wells]; Bateman found remains of at least twelve skeletons [SUPPORTED: https://en.wikipedia.org/wiki/Five_Wells]"}]'::jsonb),
    ('42ecfbef-1771-4381-ae2f-6f0f65b03309'::uuid, 'card_description', 'Underground on the island of Milos lie the Catacombs of Milos, a Christian cemetery of the 1st-5th century AD, with tombs cut into its walls and graves covered with unworked stones.', 'An underground Christian cemetery from the 1st–5th century AD, carved into volcanic rock. One of only three catacomb complexes known outside Rome.', 'teaser-card-s018-rollback:42ecfbef-1771-4381-ae2f-6f0f65b03309:card_description', 'rollback of teaser-card-s018: card_description ''An underground Christian cemetery from the 1st–5th century AD, carved into volcanic rock. One of only three catacomb complexes known outside Rome.'' restored on Catacombs of Milos', '54706776552610be4947075e3461d09101785952f0a15484822a753b94d09522|67dfe031e739714a89f03bacf2650c799f14dfdb10ad47292217a1f121b88679|67dfe031e739714a89f03bacf2650c799f14dfdb10ad47292217a1f121b88679', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-009", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Underground on the island of Milos lie the Catacombs of Milos, a Christian cemetery of the 1st-5th century AD, with tombs cut into its walls and graves covered with unworked stones."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-009 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the site is underground [S1]; it lies on the island of Milos [S1]; it is called the Catacombs of Milos [S1]; it is a Christian cemetery [S1]; it dates to the 1st-5th century AD [S1]; tombs are cut into its walls [S4]; graves are covered with unworked stones [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-025 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Catacombs of Milos are a cemetery (central claim: what kind of place). [SUPPORTED: https://en.wikipedia.org/wiki/Catacombs_of_Milos]; The cemetery is Christian. [SUPPORTED: https://en.wikipedia.org/wiki/Catacombs_of_Milos]; The catacombs are on the island of Milos (Greece). [SUPPORTED: https://en.wikipedia.org/wiki/Catacombs_of_Milos]; The cemetery dates to the 1st-5th century AD. [SUPPORTED: https://en.wikipedia.org/wiki/Catacombs_of_Milos]; The site lies underground. [SUPPORTED: https://en.wikipedia.org/wiki/Catacombs_of_Milos]; There are tombs cut into the walls of the galleries. [SUPPORTED: https://en.wikipedia.org/wiki/Catacombs_of_Milos]; Graves are covered with unworked stones. [SUPPORTED: https://en.wikipedia.org/wiki/Catacombs_of_Milos]"}]'::jsonb),
    ('437d6dda-8c48-4142-91fe-575c140b961a'::uuid, 'card_description', 'On Ramsley Moor in the Peak District, in a field of cairns, Barbrook One sets one standing stone and 11 smaller ones in a circle about 13 metres across, ringed by a rubble bank.', 'A stone circle on Ramsley Moor with one tall standing stone and 11 smaller ones, ringed by a rubble bank. It sits in a broader cairn field dotted with burial monuments.', 'teaser-card-s018-rollback:437d6dda-8c48-4142-91fe-575c140b961a:card_description', 'rollback of teaser-card-s018: card_description ''A stone circle on Ramsley Moor with one tall standing stone and 11 smaller ones, ringed by a rubble bank. It sits in a broader cairn field dotted with burial monuments.'' restored on Barbrook One', '58e4d24d265574ec167aad2c8c1f1f8d7c3af510f9f740a272ba8200a719d23c|31275141a391fd94eac59ae9c6270a5f7c66a3ddd16e7090792149ef6a22b12c|31275141a391fd94eac59ae9c6270a5f7c66a3ddd16e7090792149ef6a22b12c', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-009", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "On Ramsley Moor in the Peak District, in a field of cairns, Barbrook One sets one standing stone and 11 smaller ones in a circle about 13 metres across, ringed by a rubble bank."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-009 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the site is on Ramsley Moor [S1, S5]; it is in the Peak District [S1]; it stands in a field of cairns [S5]; it is called Barbrook One [S1]; it has one standing stone [S3]; it has 11 smaller stones [S3]; the stones are set in a circle [S1, S2]; the circle is about 13 metres across [S4]; the circle is ringed by a rubble bank [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-025 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026