    ('43d64ea4-8c7e-4bca-bcfe-04b4e6e6b437'::uuid, 'card_description', 'In Samshvilde, a ruined fortified city, a citadel stands on a rocky river promontory, and excavations revealed early Bronze Age layers with a circular cult building and obsidian tools.', 'A fortified city spanning the 3rd century BC to the 18th century AD, with mostly medieval ruins stretching 2.5 km. Twenty centuries of continuous habitation.', 'teaser-card-s018-rollback:43d64ea4-8c7e-4bca-bcfe-04b4e6e6b437:card_description', 'rollback of teaser-card-s018: card_description ''A fortified city spanning the 3rd century BC to the 18th century AD, with mostly medieval ruins stretching 2.5 km. Twenty centuries of continuous habitation.'' restored on Samshvilde', '120896eb89f18930c86f97b76fbcb703a398a233a16a7d2d081f12091fde045a|5f428541a573f4d1876bfc7e4b242cf11ddbbd0ebf70a6db51d66144104b3f16|5f428541a573f4d1876bfc7e4b242cf11ddbbd0ebf70a6db51d66144104b3f16', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-009", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "In Samshvilde, a ruined fortified city, a citadel stands on a rocky river promontory, and excavations revealed early Bronze Age layers with a circular cult building and obsidian tools."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-009 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the place is called Samshvilde [S1]; Samshvilde is a ruined fortified city [S1]; a citadel stands there [S2]; the citadel is on a rocky river promontory [S2]; excavations revealed early Bronze Age layers [S3]; the excavated horizon included a circular cult building [S4]; obsidian tools were found there [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-025 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quo