    ('44354857-115b-44d3-b155-cae373565602'::uuid, 'card_description', 'The Brauroneion, sanctuary of Artemis on the Athenian Acropolis, had no formal temple, only a stoa. Pausanias records an over-life-sized bronze horse there, representing the Trojan Horse.', 'The Acropolis sanctuary of Artemis Brauronia, of unusual trapezoidal shape. It had no formal temple -- just an open precinct with a stoa to display offerings.', 'teaser-card-s018-rollback:44354857-115b-44d3-b155-cae373565602:card_description', 'rollback of teaser-card-s018: card_description ''The Acropolis sanctuary of Artemis Brauronia, of unusual trapezoidal shape. It had no formal temple -- just an open precinct with a stoa to display offerings.'' restored on Brauroneion', '4805b77bc1eb9f89a287022eb57bd95ed7ad0fd127edb49237f0713d113c8a90|fc2ebba8d2e04b53443924ee686e21a1366f749a05c94e40d311379cce0299fa|fc2ebba8d2e04b53443924ee686e21a1366f749a05c94e40d311379cce0299fa', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-009", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Brauroneion, sanctuary of Artemis on the Athenian Acropolis, had no formal temple, only a stoa. Pausanias records an over-life-sized bronze horse there, representing the Trojan Horse."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-009 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "it is called the Brauroneion [S1]; it was a sanctuary of Artemis [S1]; it stood on the Athenian Acropolis [S1]; it had no formal temple [S3]; a stoa served in place of a temple [S3, S4]; Pausanias records an over-life-sized bronze horse at the sanctuary [S8]; the bronze horse represented the Trojan Horse [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-025 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.j