    ('739f3b71-4f87-4f30-9a58-de5e2c95f0af'::uuid, 'card_description', 'Within Leigh Woods, above the banks of the River Avon, Burgh Walls Camp is a multivallate Iron Age hill fort, one of three fortifications overlooking the Avon Gorge.', 'Multivallate Iron Age hill fort overlooking the Avon Gorge in Somerset, one of three Iron Age fortifications defending this strategic river approach. Also known as Bower Walls and Burwalls.', 'teaser-card-s018-rollback:739f3b71-4f87-4f30-9a58-de5e2c95f0af:card_description', 'rollback of teaser-card-s018: card_description ''Multivallate Iron Age hill fort overlooking the Avon Gorge in Somerset, one of three Iron Age fortifications defending this strategic river approach. Also known as Bower Walls and Burwalls.'' restored on Burgh Walls Camp', '42661f5350578312592a839801c51c10d767a56125b520ea5966b11b088b5153|3f8db648d23a18428c74c6ceceb6f53ecc49746dc349036a23658b94e07754c7|3f8db648d23a18428c74c6ceceb6f53ecc49746dc349036a23658b94e07754c7', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-013", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Within Leigh Woods, above the banks of the River Avon, Burgh Walls Camp is a multivallate Iron Age hill fort, one of three fortifications overlooking the Avon Gorge."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-013 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the site is within Leigh Woods [S2]; it is above the banks of the River Avon [S2]; it is a multivallate hill fort [S1]; it is Iron Age [S1]; it is one of three fortifications [S4]; the three fortifications overlook the Avon Gorge [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-039 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Burgh Walls Camp is an Iron Age hill fort (the central claim: a hill fort) [SUPPORTED: https://en.wikipedia.org/wiki/Burgh_Walls_Camp]; The hill fort dates to the Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Burgh_Walls_Camp]; The hill fort is multivallate [SUPPORTED: https://en.wikipedia.org/wiki/Burgh_Walls_Camp]; The hill fort lies within Leigh Woods [SUPPORTED: https://en.wikipedia.org/wiki/Burgh_Walls_Camp]; The hill fort lies above the banks of the River Avon [SUPPORTED: https://en.wikipedia.org/wiki/Burgh_Walls_Camp]; It is one of three fortifications overlooking the Avon Gorge [SUPPORTED: https://en.wikipedia.org/wiki/Burgh_Walls_Camp]"}]'::jsonb),
    ('74bda98e-3c30-4945-926c-4563ccfbf13f'::uuid, 'card_description', 'Les Ferreres Aqueduct strides on two levels of arches, 25 above and 11 below, each 20 Roman feet across, rising to a maximum height of 27 metres over a length of 249 metres.', 'A two-tiered Roman aqueduct bridge from the reign of Augustus, standing 27 metres high. Known locally as the ''Devil''s Bridge'' — people assumed only supernatural power could build it.', 'teaser-card-s018-rollback:74bda98e-3c30-4945-926c-4563ccfbf13f:card_description', 'rollback of teaser-card-s018: card_description "A two-tiered Roman aqueduct bridge from the reign of Augustus, standing 27 metres high. Known locally as the ''Devil''s Bridge'' — people assumed only supernatural power could build it." restored on Les Ferreres Aqueduct', 'fac835e6b149b229ee4fdc846e76eb61763a66026c7f9549e6334bebc4f96c40|649d7c84464bf542a217452b80e46c1801fcbaff313551417b27c2f8e473611f|649d7c84464bf542a217452b80e46c1801fcbaff313551417b27c2f8e473611f', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-013", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Les Ferreres Aqueduct strides on two levels of arches, 25 above and 11 below, each 20 Roman feet across, rising to a maximum height of 27 metres over a length of 249 metres."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-013 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the aqueduct has two levels of arches [S1]; the upper level has 25 arches [S1]; the lower level has 11 arches [S1]; each arch is 20 Roman feet across (diameter) [S2]; its maximum height is 27 metres [S4]; its length is 249 metres [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-039 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Les Ferreres Aqueduct is a Roman aqueduct bridge near Tarragona, Spain (the central claim: an aqueduct) [SUPPORTED: https://en.wikipedia.org/wiki/Les_Ferreres_Aqueduct]; It has two levels of arches [SUPPORTED: https://en.wikipedia.org/wiki/Les_Ferreres_Aqueduct]; The upper level has 25 arches [SUPPORTED: https://en.wikipedia.org/wiki/Les_Ferreres_Aqueduct]; The lower level has 11 arches [SUPPORTED: https://en.wikipedia.org/wiki/Les_Ferreres_Aqueduct]; Each arch is 20 Roman feet across [SUPPORTED: https://en.wikipedia.org/wiki/Les_Ferreres_Aqueduct]; Its maximum height is 27 metres [SUPPORTED: https://en.wikipedia.org/wiki/Les_Ferreres_Aqueduct]; Its length is 249 metres [SUPPORTED: https://en.wikipedia.org/wiki/Les_Ferreres_Aqueduct]"}]'::jsonb),
    ('75374382-c6a7-4fb5-b9fb-cb1cd29fd7f2'::uuid, 'card_description', 'The Stoa of Eumenes rose south of the Asklepieion staircase, its arcade built along an arched wall that retained the pathway to the north. A substantial part of the northern wall survives.', 'A gallery donated by King Eumenes II around 160 BC as shelter for theatre spectators. It connected the Theatre of Dionysus to the Odeon of Herodes Atticus.', 'teaser-card-s018-rollback:75374382-c6a7-4fb5-b9fb-cb1cd29fd7f2:card_description', 'rollback of teaser-card-s018: card_description ''A gallery donated by King Eumenes II around 160 BC as shelter for theatre spectators. It connected the Theatre of Dionysus to the Odeon of Herodes Atticus.'' restored on Stoa of Eumenes', 'dcf7592b668160e7324ef615f410ce75d649e4162aff73ba7b557e4547a549bd|de82a11d49240dfec40f805982ab62f6df3ede2a0fb502612e792936115689b9|de82a11d49240dfec40f805982ab62f6df3ede2a0fb502612e792936115689b9', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-rewrite-v-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Stoa of Eumenes rose south of the Asklepieion staircase, its arcade built along an arched wall that retained the pathway to the north. A substantial part of the northern wall survives."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-v-002 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the Stoa of Eumenes was built south of the Asklepieion staircase [S1]; its arcade was built along an arched wall [S2, S3]; the arched wall retained the pathway to the north [S2]; a substantial part of the northern wall survives [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify2-006 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Stoa of Eumenes was a stoa (colonnade) on the south slope of the Acropolis, Athens [SUPPORTED: https://en.wikipedia.org/wiki/Stoa_of_Eumenes]; The stoa was built south of the Asklepieion staircase [SUPPORTED: https://en.wikipedia.org/wiki/Stoa_of_Eumenes]; Its arcade was built along an arched wall that retained the pathway to the north [SUPPORTED: https://en.wikipedia.org/wiki/Stoa_of_Eumenes]; The arcade was built along that retaining wall [SUPPORTED: https://en.wikipedia.org/wiki/Stoa_of_Eumenes]; A substantial part of the northern wall survives [SUPPORTED: https://en.wikipedia.org/wiki/Stoa_of_Eumenes]"}]'::jsonb),
    ('76220eb6-d405-4d79-a0a7-d36c4809094f'::uuid, 'card_description', 'Near Elmsted in Kent, Shrub''s Wood Long Barrow still stands 2 metres high at its eastern end. Probably raised in the fourth millennium BCE, it has yet to be thoroughly investigated.', 'An Early Neolithic long barrow from the 4th millennium BC, built of earth. Unchambered barrows like this held the dead but had no accessible burial room.', 'teaser-card-s018-rollback:76220eb6-d405-4d79-a0a7-d36c4809094f:card_description', 'rollback of teaser-card-s018: card_description ''An Early Neolithic long barrow from the 4th millennium BC, built of earth. Unchambered barrows like this held the dead but had no accessible burial room.'' restored on Shrub''s Wood Long Barrow', '844b152496e79b94e2704400807ae733c57bbf2a5de5821046a1ac41be773811|15297233ca45f7c909c8fb812eb070e4a2cf89d941bbf93d7ab103f9172b1dd9|15297233ca45f7c909c8fb812eb070e4a2cf89d941bbf93d7ab103f9172b1dd9', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-013", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Near Elmsted in Kent, Shrub''s Wood Long Barrow still stands 2 metres high at its eastern end. Probably raised in the fourth millennium BCE, it has yet to be thoroughly investigated."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-013 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the barrow is near Elmsted [S1]; it is in Kent [S1]; it still stands 2 metres high at its eastern end [S5, S6]; it was probably raised in the fourth millennium BCE (hedge kept) [S2]; it has yet to be thoroughly investigated (implies unexplored) [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-039 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Shrub''s Wood Long Barrow is an unchambered long barrow (tomb mound) near Elmsted in Kent, England (the central claim: a long barrow) [SUPPORTED: https://en.wikipedia.org/wiki/Shrub%27s_Wood_Long_Barrow]; The barrow lies near the village of Elmsted [SUPPORTED: https://en.wikipedia.org/wiki/Shrub%27s_Wood_Long_Barrow]; The barrow still stands 2 metres high at its eastern end [SUPPORTED: https://en.wikipedia.org/wiki/Shrub%27s_Wood_Long_Barrow]; It was probably raised in the fourth millennium BCE [SUPPORTED: https://en.wikipedia.org/wiki/Shrub%27s_Wood_Long_Barrow]; It has yet to be thoroughly investigated [SUPPORTED: https://en.wikipedia.org/wiki/Shrub%27s_Wood_Long_Barrow]"}]'::jsonb),
    ('7797f819-742d-44a1-9df8-f412d513e54a'::uuid, 'card_description', 'Near Caraz, the fine stonework of Tumshukayko rises in a circle of platforms, terraces and stairways, and its stone heads and triangular stones suggest a link to the early Chavín culture.', NULL, 'teaser-card-s018-rollback:7797f819-742d-44a1-9df8-f412d513e54a:card_description', 'rollback of teaser-card-s018: card_description None restored on Tumshukayko', '27b770586e93537a7006f31804158e5703b324bcaefa2e522737c33fc8270ef7|54cc4a2a7c1385317578ed3ff13ad0e406ba13a936e1c951f7eac0fdd4bd21f6|54cc4a2a7c1385317578ed3ff13ad0e406ba13a936e1c951f7eac0fdd4bd21f6', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-014", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Near Caraz, the fine stonework of Tumshukayko rises in a circle of platforms, terraces and stairways, and its stone heads and triangular stones suggest a link to the early Chavín culture."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-014 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the site lies near Caraz [S1, S5]; the stonework of Tumshukayko is fine [S6]; the stonework forms a circular structure [S6]; the structure consists of platforms, terraces and stairways [S6]; the site has stone heads and triangular stones [S7]; the stone heads and triangular stones suggest a connection to the early Chavín culture [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-040 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Tumshukayko is an archaeological site (a pre-Inca monumental centre) near Caraz, Peru [SUPPORTED: https://en.wikipedia.org/wiki/Tumshukayko]; The site has fine stonework [SUPPORTED: https://en.wikipedia.org/wiki/Tumshukayko]; The structure rises in a circle [SUPPORTED: https://en.wikipedia.org/wiki/Tumshukayko]; The circular structure consists of platforms, terraces and stairways [SUPPORTED: https://en.wikipedia.org/wiki/Tumshukayko]; Stone heads are among its most outstanding artefacts [SUPPORTED: https://en.wikipedia.org/wiki/Tumshukayko]; Triangular stones are among its most outstanding artefacts [SUPPORTED: https://en.wikipedia.org/wiki/Tumshukayko]; The stone heads and triangular stones suggest a link to the early Chavín culture [SUPPORTED: https://en.wikipedia.org/wiki/Tumshukayko]"}]'::jsonb),
    ('77aa7ece-0acc-4765-b8ae-be5e0763d9ef'::uuid, 'card_description', 'At Ban Non Wat, Iron Age dead went to their graves with carnelian, agate and glass. Later, banks and two moats ringed the site, and archaeologists uncovered about a dozen working floors.', 'A village site with 11 prehistoric phases spanning Neolithic to Iron Age, including 640 burials. The graves reveal one of Southeast Asia''s earliest bronze-working cultures.', 'teaser-card-s018-rollback:77aa7ece-0acc-4765-b8ae-be5e0763d9ef:card_description', 'rollback of teaser-card-s018: card_description "A village site with 11 prehistoric phases spanning Neolithic to Iron Age, including 640 burials. The graves reveal one of Southeast Asia''s earliest bronze-working cultures." restored on Ban Non Wat', 'cbd707861484d1839bab35298cdb4c6ab03c0d04cc1ebfc27ef13f48a006d871|102feb53c3ee3f58414144cfe6bda326745998bcfb6f257e7864f9678ab5feb7|102feb53c3ee3f58414144cfe6bda326745998bcfb6f257e7864f9678ab5feb7', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-014", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "At Ban Non Wat, Iron Age dead went to their graves with carnelian, agate and glass. Later, banks and two moats ringed the site, and archaeologists uncovered about a dozen working floors."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-014 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "in the Iron Age the dead were accompanied into their graves by carnelian, agate and glass [S3]; later in the Iron Age the site was surrounded by banks [S4]; later in the Iron Age the site was surrounded by two moats [S4]; archaeologists uncovered about a dozen working floors [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-040 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Ban Non Wat is an archaeological site (an excavated prehistoric village with burials) in Thailand [SUPPORTED: https://en.wikipedia.org/wiki/Ban_Non_Wat]; Iron Age dead at Ban Non Wat were buried with carnelian, agate and glass [SUPPORTED: https://en.wikipedia.org/wiki/Ban_Non_Wat]; Later, the site was surrounded by banks and two moats [SUPPORTED: https://en.wikipedia.org/wiki/Ban_Non_Wat]; Archaeologists uncovered about a dozen working floors [SUPPORTED: https://en.wikipedia.org/wiki/Ban_Non_Wat]"}]'::jsonb),
    ('77c38659-cde8-4de5-9c1a-5a2d4d2125eb'::uuid, 'card_description', 'Roman Lutetia was laid out along the Cardo Maximus. Its grand public baths, the Thermes de Cluny, are its largest and best-preserved vestige, from the late 1st or early 2nd century AD.', 'The Gallo-Roman predecessor of Paris, founded by the Parisii tribe at a key river crossing. Its amphitheatre, baths, and forum lie beneath the modern city''s streets.', 'teaser-card-s018-rollback:77c38659-cde8-4de5-9c1a-5a2d4d2125eb:card_description', 'rollback of teaser-card-s018: card_description "The Gallo-Roman predecessor of Paris, founded by the Parisii tribe at a key river crossing. Its amphitheatre, baths, and forum lie beneath the modern city''s streets." restored on Lutetia', '29f0f6f1dfaaa0b6e58ac1a2d95f8d5327fbc128ea3bad50e8289014ad634035|849476e9e05a1989ce15f3f768968af12e3a5c387bc3f43e47883e155b42651c|849476e9e05a1989ce15f3f768968af12e3a5c387bc3f43e47883e155b42651c', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-014", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Roman Lutetia was laid out along the Cardo Maximus. Its grand public baths, the Thermes de Cluny, are its largest and best-preserved vestige, from the late 1st or early 2nd century AD."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-014 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Roman Lutetia was laid out along the Cardo Maximus [S3]; the Thermes de Cluny are the grand public baths of Roman Lutetia [S4]; the Thermes de Cluny are the largest vestige of Roman Lutetia [S4]; the Thermes de Cluny are the best-preserved vestige of Roman Lutetia [S4]; the Thermes de Cluny date from the late 1st or early 2nd century AD [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-040 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Lutetia was a Roman (Gallo-Roman) town, predecessor of modern Paris, France [SUPPORTED: https://en.wikipedia.org/wiki/Lutetia]; Roman Lutetia was laid out along the Cardo Maximus [SUPPORTED: https://en.wikipedia.org/wiki/Lutetia]; The Thermes de Cluny are the grand public baths of Roman Lutetia [SUPPORTED: https://en.wikipedia.org/wiki/Lutetia]; The Thermes de Cluny are the largest vestige of Roman Lutetia [SUPPORTED: https://en.wikipedia.org/wiki/Lutetia]; The Thermes de Cluny are the best-preserved vestige of Roman Lutetia [SUPPORTED: https://en.wikipedia.org/wiki/Lutetia]; The Thermes de Cluny date from the late 1st or early 2nd century AD [SUPPORTED: https://en.wikipedia.org/wiki/Lutetia]"}]'::jsonb),
    ('79484b17-4db6-454c-aacb-a3cb5eafaec9'::uuid, 'card_description', 'In 1006, the Anglo-Saxon Chronicle says, Danes marched to Scutchamer Knob, an early Iron Age round barrow, believing that if they reached the hill they would never return to the sea.', 'Known as Cwichelm''s Barrow, this Iron Age round barrow on the Oxfordshire Ridgeway marks where King Edwin killed Cwichelm of Wessex in 636 AD. It later served as the shire moot meeting point.', 'teaser-card-s018-rollback:79484b17-4db6-454c-aacb-a3cb5eafaec9:card_description', 'rollback of teaser-card-s018: card_description "Known as Cwichelm''s Barrow, this Iron Age round barrow on the Oxfordshire Ridgeway marks where King Edwin killed Cwichelm of Wessex in 636 AD. It later served as the shire moot meeting point." restored on Scutchamer Knob', '37a5cbbc255fbdcdb2ba865daab8516df625545cb012b2d039ff28af5efc3dcc|13c2a1192416361ab90cd566a86b7df77fc50712f00e8e914097cab913156ff8|13c2a1192416361ab90cd566a86b7df77fc50712f00e8e914097cab913156ff8', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-014", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "In 1006, the Anglo-Saxon Chronicle says, Danes marched to Scutchamer Knob, an early Iron Age round barrow, believing that if they reached the hill they would never return to the sea."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-014 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "in 1006 the Anglo-Saxon Chronicle records that Danes marched to the hill (Cuckhamsley Hill, another name of Scutchamer Knob) [S1, S4]; Scutchamer Knob is an early Iron Age round barrow [S1]; the Danes believed that if they reached the hill they would never return to the sea [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-040 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Scutchamer Knob (also called Cuckhamsley Hill) is an early Iron Age round barrow [SUPPORTED: https://en.wikipedia.org/wiki/Scutchamer_Knob]; In 1006 the Anglo-Saxon Chronicle says the Danes marched to Scutchamer Knob (Cuckhamsley Hill) [SUPPORTED: https://en.wikipedia.org/wiki/Scutchamer_Knob]; The Danes believed that if they reached the hill they would never return to the sea [SUPPORTED: https://en.wikipedia.org/wiki/Scutchamer_Knob]"}]'::jsonb),
    ('7b2aa41c-d24b-4c4c-8ee1-cc0bc461d18c'::uuid, 'card_description', 'Half dug into a hill, the Uthina Amphitheatre dates from the reign of Hadrian and seated about 16,000. Below its arena, an underground vaulted gallery leads to symmetrical vaults and rooms.', 'An amphitheatre half-carved into a hillside, seating 16,000. Underground vaulted galleries and symmetrical chambers lie beneath the arena floor.', 'teaser-card-s018-rollback:7b2aa41c-d24b-4c4c-8ee1-cc0bc461d18c:card_description', 'rollback of teaser-card-s018: card_description ''An amphitheatre half-carved into a hillside, seating 16,000. Underground vaulted galleries and symmetrical chambers lie beneath the arena floor.'' restored on Uthina Amphitheatre', '6bdcdd2c69d079d848a03c35668e02214b99af0b8e5443dd3cf25c47395da63c|716f612678b72eed0727fe3a0cdbd4afa1055d776ac4f89c4c9952c3aa13bf4c|716f612678b72eed0727fe3a0cdbd4afa1055d776ac4f89c4c9952c3aa13bf4c', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-014", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Half dug into a hill, the Uthina Amphitheatre dates from the reign of Hadrian and seated about 16,000. Below its arena, an underground vaulted gallery leads to symmetrical vaults and rooms."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-014 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the amphitheatre is half dug into a hill [S3]; the amphitheatre dates from the reign of Hadrian [S4]; it seated about 16,000 [S4]; below the arena an underground vaulted gallery gives access to the basement [S7]; the basement has symmetrical vaults and rooms under the central arena [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-040 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Uthina Amphitheatre is a Roman amphitheatre in the former city of Uthina (Oudna), Tunisia [SUPPORTED: https://en.wikipedia.org/wiki/Uthina]; The amphitheatre is half dug into a hill [SUPPORTED: https://en.wikipedia.org/wiki/Uthina]; It dates from the reign of Hadrian [SUPPORTED: https://en.wikipedia.org/wiki/Uthina]; It seated about 16,000 [SUPPORTED: https://en.wikipedia.org/wiki/Uthina]; Below the arena an underground vaulted gallery leads to symmetrical vaults and rooms [SUPPORTED: https://en.wikipedia.org/wiki/Uthina]"}]'::jsonb);

DO $$
DECLARE
    bad      INTEGER;
    moved    INTEGER := 0;
    expected INTEGER := 100;
    r        RECORD;
BEGIN
    -- expected is the plan's own row count, rendered here, and not a second count of the
    -- temp table the loop below iterates: counting the same table twice would make the
    -- comparison after the loop a tautology. The instance that makes a short loop
    -- unreachable is apply_remediation_change, which raises unless exactly one row
    -- matched; this guard is what reports a loop that changed fewer rows than the plan.

    -- scope guard 1: every planned row is a card_stats row of a curated site that still exists
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN card_stats t ON t.site_id = p.site_id
      LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE t.site_id IS NULL OR u.id IS NULL OR u.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        -- the source name is a RAISE argument, never part of the quoted message: a name
        -- spliced into the message text only parses while the name happens to contain no
        -- quote, which is a property of today's value and not of this code. G0's guard is
        -- the shape this one copies.
        RAISE EXCEPTION 'teaser card: % planned row(s) are not % sites', bad, 'ancient_nerds';
    END IF;

    -- scope guard 2: the plan is a set of real changes, each one writable in its column
    -- (compared in the column's own type; CASE, because only CASE fixes the order in
    -- which the casts are evaluated)
    SELECT count(*) INTO bad FROM _teaser_card_plan p
     WHERE p.new_value = '' OR CASE p.column_name
                WHEN 'card_description' THEN p.new_value::character varying IS NOT DISTINCT FROM p.old_value::character varying OR length(p.new_value) > 200
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) are not writable changes', bad;
    END IF;

    -- scope guard 3: every planned row still holds the old value the plan names
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.old_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the planned old value', bad;
    END IF;

    -- scope guard 5: every planned row still holds the input its value was derived from
    SELECT count(*) INTO bad
      FROM (SELECT DISTINCT site_id, premise FROM _teaser_card_plan) p JOIN unified_sites u ON u.id = p.site_id
     WHERE (coalesce(u.raw_data -> '_card_provenance' ->> 'text_sha256', '') || '|' || coalesce(u.raw_data -> '_card_provenance' ->> 'desc_sha256', '') || '|' || encode(sha256(convert_to(coalesce(u.description, ''), 'UTF8')), 'hex')) IS DISTINCT FROM p.premise;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the premise the plan derived its value from', bad;
    END IF;

    -- the only writer: the conditional UPDATE and its journal row commit together, and
    -- the function raises unless exactly one row matched
    FOR r IN SELECT * FROM _teaser_card_plan ORDER BY site_id, column_name LOOP
        moved := moved + apply_remediation_change(
            'card_stats', r.column_name, 'site_id', r.site_id::text,
            r.old_value, r.new_value,
            'WB/teaser-card', 'wb-teaser-card-s018-rollback', r.change_key, 'opus-checked', r.evidence, r.site_id);
    END LOOP;

    IF moved <> expected THEN
        RAISE EXCEPTION 'teaser card: % row(s) changed, % planned', moved, expected;
    END IF;

    -- invariant 1: every planned row now holds the new value
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.new_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) do not hold the new value', bad;
    END IF;

    -- invariant 2: the journal and the data agree, row for row, in both directions
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN remediation_change_log l
        ON l.row_pk = p.site_id::text AND l.table_name = 'card_stats'
       AND l.column_name = p.column_name
       AND l.run_stamp = 'wb-teaser-card-s018-rollback'
     WHERE l.id IS NULL
        OR l.new_value IS DISTINCT FROM p.new_value
        OR l.old_value IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) have no matching journal row', bad;
    END IF;

    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = 'wb-teaser-card-s018-rollback'
       AND (l.table_name <> 'card_stats' OR l.column_name NOT IN ('card_description'));
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: this run stamp journalled % row(s) outside card_stats.(card_description)', bad;
    END IF;

    RAISE NOTICE 'teaser card: % of % planned cell(s) changed and journalled over 100 curated site(s)',
        moved, expected;
END $$;

COMMIT;

-- Post-commit read: the numbers the report quotes, from the database, not from the plan.
SELECT 'journal rows for this run stamp' AS metric, count(*)::text AS value
  FROM remediation_change_log WHERE run_stamp = 'wb-teaser-card-s018-rollback'
UNION ALL
SELECT 'journal rows for this test id', count(*)::text
  FROM remediation_change_log WHERE test_id = 'WB/teaser-card'
UNION ALL
SELECT 'planned rows now holding the new value', count(*)::text
  FROM remediation_change_log l
 WHERE l.run_stamp = 'wb-teaser-card-s018-rollback' AND l.table_name = 'card_stats'
   AND l.column_name IN ('card_description')
   AND EXISTS (SELECT 1 FROM card_stats t
                WHERE t.site_id::text = l.row_pk AND CASE l.column_name
                WHEN 'card_description' THEN t.card_description IS NOT DISTINCT FROM l.new_value::character varying
                ELSE false END)
UNION ALL
SELECT 'curated sites whose teaser provenance does not hash their live card', count(*)::text
  FROM unified_sites
 WHERE source_id = 'ancient_nerds' AND raw_data ? '_card_provenance' AND NOT EXISTS (SELECT 1 FROM card_stats cs WHERE cs.site_id = unified_sites.id AND encode(sha256(convert_to(cs.card_description, 'UTF8')), 'hex') = unified_sites.raw_data -> '_card_provenance' ->> 'text_sha256')
UNION ALL
SELECT 'curated sites', count(*)::text
  FROM unified_sites WHERE source_id = 'ancient_nerds';
